The code below is replicated in a bunch of different places (random forest models and a few others). It should be a documented, exportable function (and it can be made less ugly):

```
rftGrid <- function(x, y, len = NULL)
{
  p <- ncol(x)
  if (len == 1) {
    tuneSeq <- if (!is.factor(y)) 
      max(floor(p/3), 1)
    else floor(sqrt(p))
  }
  else {
    if (p <= len) {
      tuneSeq <- floor(seq(2, to = p, length = p))
    }
    else {
      if (p < 500) 
        tuneSeq <- floor(seq(2, to = p, length = len))
      else tuneSeq <- floor(2^seq(1, to = log(p, base = 2), 
                                  length = len))
    }
  }
  if (any(table(tuneSeq) > 1)) {
    tuneSeq <- unique(tuneSeq)
    cat("note: only", length(tuneSeq), "unique complexity parameters in default grid.", 
        "Truncating the grid to", length(tuneSeq), ".\n\n")
  }
  data.frame(expand.grid(mtry = tuneSeq,maxdepth=seq(1,7)))
}
